module.exports = {
    onConnect: function(transport, config) {
        engine.setStatus("connected", "VLC Media Player HTTP Ready");
    },
    onAction: function(transport, actionId, params) {
        var password = engine.secret("password") || "";
        var authHeader = password ? { "Authorization": "Basic " + engine.crypto.base64Encode(":" + password) } : {};

        if (actionId === "vlc_play_pause" || actionId === "play_pause") {
            return engine.http.get("/requests/status.json?command=pl_pause", authHeader).then(function(res) {
                if (res.json && res.json.state) {
                    engine.setVariable("vlc_state", res.json.state);
                }
                return "Toggled Play/Pause";
            });
        }
        if (actionId === "vlc_stop" || actionId === "stop") {
            return engine.http.get("/requests/status.json?command=pl_stop", authHeader).then(function(res) {
                engine.setVariable("vlc_state", "stopped");
                return "Stopped Playback";
            });
        }
        if (actionId === "vlc_volume" || actionId === "set_volume") {
            var val = params.volume || "256";
            return engine.http.get("/requests/status.json?command=volume&val=" + val, authHeader).then(function(res) {
                engine.setVariable("vlc_volume", String(val));
                return "Set Volume to " + val;
            });
        }
        return "VLC Action Executed";
    }
};
